import * as THREE from 'three';

/* ---------- renderer / scene / camera ---------- */

const renderer = new THREE.WebGLRenderer({ antialias: true });
renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
renderer.setSize(window.innerWidth, window.innerHeight);
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.05;
document.body.appendChild(renderer.domElement);

const scene = new THREE.Scene();
scene.fog = new THREE.Fog(0xf0b08a, 130, 430);

const camera = new THREE.PerspectiveCamera(50, window.innerWidth / window.innerHeight, 0.1, 2000);
const camBase = new THREE.Vector3(0, 9, 62);
const camLook = new THREE.Vector3(-4, 15, -60);
camera.position.copy(camBase);
camera.lookAt(camLook);

/* ---------- helpers ---------- */

function hash(x, z) {
  const s = Math.sin(x * 127.1 + z * 311.7) * 43758.5453;
  return s - Math.floor(s);
}
function noise2(x, z) {
  const xi = Math.floor(x), zi = Math.floor(z);
  const xf = x - xi, zf = z - zi;
  const u = xf * xf * (3 - 2 * xf), v = zf * zf * (3 - 2 * zf);
  const a = hash(xi, zi), b = hash(xi + 1, zi), c = hash(xi, zi + 1), d = hash(xi + 1, zi + 1);
  return a + (b - a) * u + (c - a) * v + (a - b - c + d) * u * v;
}
const lerp = (a, b, t) => a + (b - a) * t;
const smooth01 = t => { t = THREE.MathUtils.clamp(t, 0, 1); return t * t * (3 - 2 * t); };

/* ---------- dusk sky dome (procedural gradient) ---------- */

const skyMat = new THREE.ShaderMaterial({
  side: THREE.BackSide,
  depthWrite: false,
  uniforms: {
    uTop:   { value: new THREE.Color(0x1c2a5e) },
    uMid:   { value: new THREE.Color(0xb0688f) },
    uLow:   { value: new THREE.Color(0xffb37a) },
    uFloor: { value: new THREE.Color(0xe89a72) }
  },
  vertexShader: `
    varying vec3 vDir;
    void main() {
      vDir = normalize(position);
      gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
    }`,
  fragmentShader: `
    uniform vec3 uTop, uMid, uLow, uFloor;
    varying vec3 vDir;
    void main() {
      float h = vDir.y;
      vec3 col = mix(uLow, uMid, smoothstep(0.02, 0.35, h));
      col = mix(col, uTop, smoothstep(0.30, 0.85, h));
      col = mix(uFloor, col, smoothstep(-0.08, 0.01, h));
      gl_FragColor = vec4(col, 1.0);
    }`
});
scene.add(new THREE.Mesh(new THREE.SphereGeometry(500, 24, 16), skyMat));

/* faint early stars near the zenith */
{
  const n = 140, pos = new Float32Array(n * 3);
  for (let i = 0; i < n; i++) {
    const v = new THREE.Vector3().randomDirection();
    if (v.y < 0.55) { i--; continue; }
